3f68cfe7f95fdfd770274ece724d3623c361f4a0:
query TodoListQuery {
  todos {
    id
    ...TodoItem_todo
  }
}

fragment TodoItem_todo on Todo {
  title
  done
}

7b287a25c92827de62ee76b0bdbdc3a1f06652f8:
mutation AddTodoFormMutation(
  $input: AddTodoInput!
) {
  addTodo(input: $input) {
    id
    title
  }
}

ca3885e07dab7aa341848f8d0138896377bf5af0:
mutation TodoDetailToggleMutation(
  $id: ID!
) {
  toggleTodo(id: $id) {
    id
    done
  }
}

fdcca2996f159e3306fc76535a22a6d4afcfa77d:
query UserListQuery {
  users {
    id
    name
    email
  }
}

feffca234775cf9b6036b7f757110fbf6f4094f8:
query TodoDetailQuery(
  $id: ID!
) {
  todo(id: $id) {
    id
    title
    done
    status
    owner {
      name
      id
    }
  }
}
